CREATE OR REPLACE FUNCTION public.guard_book_delivery() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user <> 'service_role' THEN IF TG_OP='INSERT' THEN IF NEW.final_pdf_path IS NOT NULL OR NEW.pdf_ready_at IS NOT NULL THEN RAISE EXCEPTION 'PDF delivery is server managed'; END IF; ELSE IF NEW.final_pdf_path IS DISTINCT FROM OLD.final_pdf_path OR NEW.pdf_ready_at IS DISTINCT FROM OLD.pdf_ready_at OR NEW.payment_total_cents IS DISTINCT FROM OLD.payment_total_cents OR NEW.checkout_session_id IS DISTINCT FROM OLD.checkout_session_id OR NEW.environment IS DISTINCT FROM OLD.environment OR NEW.base_price_cents IS DISTINCT FROM OLD.base_price_cents OR NEW.extras_cents IS DISTINCT FROM OLD.extras_cents OR NEW.shipping_cents IS DISTINCT FROM OLD.shipping_cents THEN RAISE EXCEPTION 'Payment evidence and purchased prices are server managed'; END IF; IF OLD.checkout_session_id IS NOT NULL AND (NEW.manuscript_path IS DISTINCT FROM OLD.manuscript_path OR NEW.manuscript_pages IS DISTINCT FROM OLD.manuscript_pages OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.edition IS DISTINCT FROM OLD.edition OR NEW.cover_path IS DISTINCT FROM OLD.cover_path OR NEW.extra_sections IS DISTINCT FROM OLD.extra_sections OR NEW.format IS DISTINCT FROM OLD.format) THEN RAISE EXCEPTION 'Submitted book contents are locked'; END IF; IF NEW.status='paid' AND OLD.status NOT IN ('paid','printing','shipped','delivered') THEN RAISE EXCEPTION 'Payment confirmation is server managed'; END IF; END IF; END IF; IF NEW.format='digital' AND NEW.status IN ('printing','shipped','delivered') THEN RAISE EXCEPTION 'Digital AstroBooks are downloaded, not shipped'; END IF; IF NEW.status IN ('printing','shipped','delivered') THEN IF TG_OP='INSERT' THEN RAISE EXCEPTION 'Verified payment required'; END IF; IF NEW.environment <> 'live' OR OLD.status NOT IN ('paid','printing','shipped','delivered') OR NEW.payment_total_cents IS NULL OR NEW.final_pdf_path IS NULL THEN RAISE EXCEPTION 'Live verified payment and final PDF required for production'; END IF; END IF; IF NEW.status IN ('shipped','delivered') THEN IF NEW.carrier NOT IN ('USPS','UPS','FedEx') OR trim(NEW.tracking_number)='' OR NEW.shipped_at IS NULL OR NEW.shipped_at > current_date THEN RAISE EXCEPTION 'Add a carrier, tracking and valid dispatch date'; END IF; END IF; RETURN NEW; END $$;